"Loyiha 10 ta interaktiv model (Rezerford, Kepler, matematik va prujinali mayatnik, qiya tekislik, otilgan jism, gaz qonunlari, Om qonuni, kondensator, induksiya), laboratoriya jurnali, dars ishlanmalar va onlayn testlardan iborat. Diagrammani kattalashtirish, PNG sifatida yuklab olish va chop etish mumkin.":"Проект состоит из 10 интерактивных моделей (Резерфорд, Кеплер, математический и пружинный маятник, наклонная плоскость, брошенное тело, газовые законы, закон Ома, конденсатор, индукция), лабораторного журнала, разработок уроков и онлайн-тестов. Диаграмму можно увеличить, скачать в формате PNG и распечатать.",
