"Tushuvchi nur, singan nur va normal bitta tekislikda yotadi. Muhitning absolyut sindirish ko'rsatkichi — yorug'likning vakuumdagi tezligi muhitdagi tezligidan necha marta katta ekanini bildiradi:":"Падающий луч, преломлённый луч и нормаль лежат в одной плоскости. Абсолютный показатель преломления среды показывает, во сколько раз скорость света в вакууме больше, чем в среде:",
