"U > 0 — anod musbat (tezlatuvchi maydon); U < 0 — anod manfiy (tormozlovchi maydon).":"U > 0 — анод положительный (ускоряющее поле); U < 0 — анод отрицательный (тормозящее поле).",
"U ni":"Увеличьте U в",
"U ni 2 baravar oshiring — I ham 2 baravar oshadi. R ni 2 baravar oshiring — I 2 baravar kamayadi. Zarrachalar tezligi tok kuchiga proporsional, rezistorning qizishi esa quvvatga (P = U·I) bog'liq.":"Увеличьте U в 2 раза — I тоже возрастёт в 2 раза. Увеличьте R в 2 раза — I уменьшится в 2 раза. Скорость частиц пропорциональна силе тока, а нагрев резистора зависит от мощности (P = U·I).",
"U ni 6 V ga qaytarib, R ni 2 barobar oshiring (20 Ω) — I qanday o'zgardi?":"Верните U = 6 V и увеличьте R в 2 раза (20 Ω) — как изменилась I?",
