"— beqaror atom yadrolarining o'z-o'zidan boshqa yadroga aylanishi, bunda α-zarra (geliy yadrosi), β-zarra (elektron yoki pozitron) va γ-nurlanish chiqadi. Har bir yadro uchun parchalanish —":"— самопроизвольное превращение нестабильных атомных ядер в другие ядра с испусканием α-частицы (ядра гелия), β-частицы (электрона или позитрона) и γ-излучения. Для каждого ядра распад —",
"— bikrligi k bo'lgan prujinaga mahkamlangan m massali yuk. Yuk muvozanat holatidan x ga siljiganda unga":"— груз массой m, прикреплённый к пружине жёсткостью k. При смещении груза из положения равновесия на x на него действует возвращающая сила по",
"— bir-biridan d masofada turgan ikki parallel metall qoplama. Qoplamalar orasi dielektrik (havo, parafin, slyuda, shisha) bilan to'ldirilishi mumkin. Uning":"— две параллельные металлические обкладки на расстоянии d друг от друга. Пространство между обкладками может быть заполнено диэлектриком (воздух, парафин, слюда, стекло). Его",
"— cho'zilmaydigan vaznsiz ipga osilgan moddiy nuqta. Kichik tebranishlar uchun tebranish davri faqat ip uzunligi (L) va erkin tushish tezlanishiga (g) bog'liq:":"— материальная точка, подвешенная на невесомой нерастяжимой нити. Для малых колебаний период зависит только от длины нити (L) и ускорения свободного падения (g):",
"— g'altak orqali o'tuvchi magnit oqimi o'zgarganda unda elektr yurituvchi kuch (EYK) hosil bo'lish hodisasi (M. Faradey, 1831-yil).":"— явление возникновения электродвижущей силы (ЭДС) в катушке при изменении проходящего через неё магнитного потока (М. Фарадей, 1831 г.).",
"— molekulalari o'lchami idish hajmiga nisbatan juda kichik va o'zaro faqat to'qnashganda ta'sirlashadigan gaz modeli. Uning holati bosim (p), hajm (V) va absolyut harorat (T) bilan aniqlanadi hamda":"— модель газа, размеры молекул которого очень малы по сравнению с объёмом сосуда, а взаимодействуют они только при столкновениях. Его состояние определяется давлением (p), объёмом (V) и абсолютной температурой (T) и подчиняется",
"— oddiy mexanizm: yukni to'g'ridan-to'g'ri ko'tarish o'rniga qiya yuza bo'ylab kichikroq kuch bilan tortish mumkin. Lekin ishqalanish tufayli bajarilgan ishning bir qismi isrof bo'ladi.":"— простой механизм: вместо прямого подъёма груз можно тянуть вдоль наклонной поверхности меньшей силой. Но из-за трения часть совершённой работы теряется.",
"— oddiy rezistor bunday quvvatda qattiq qizib, kuyib qolishi mumkin. Maktab laboratoriyasidagi rezistorlar odatda bir necha vattga mo'ljallangan — amalda R ni kattaroq yoki U ni kichikroq oling.":"— обычный резистор при такой мощности сильно нагреется и может сгореть. Школьные лабораторные резисторы обычно рассчитаны на несколько ватт — на практике берите R больше или U меньше.",
"— qalinligi sirtlarining egrilik radiuslaridan ancha kichik bo'lgan shaffof jism. O'rtasi chetidan qalin linza":"— прозрачное тело, толщина которого намного меньше радиусов кривизны его поверхностей. Линза, которая в середине толще, чем у краёв, —",
